import sympy as s
from functools import lru_cache
@lru_cache(None)
def parts(n,m=None):
    if m is None: return parts(n,n)
    if n==0: return ((),)
    return tuple((i,)+p for i in range(min(n,m),1-1,-1) for p in parts(n-i,i))
